function normalizeGridSize(value) {
  const requested = Number(value);
  if (Number.isSafeInteger(requested) && requested>=4) return requested;
  return DEFAULT_GRID_SIZE;
}

function normalizeScalarActivityCueGridSize(value, fallback = DEFAULT_GRID_SIZE) {
  const requested = Math.round(Number(value));
  if (Number.isFinite(requested) && requested > 0) return requested;
  return fallback;
}

function normalizeRenderScale(value) {
  const requested = Number(value);
  if (!Number.isFinite(requested)) return 0.85;
  return Math.max(0.1, Math.min(1, requested));
}

const RETIRED_RAYMARCH_CONTROL_KEYS = Object.freeze([
  'boundarySplatComposition',
  'boundarySplatFeatureCapture',
  'boundarySplatInstanceConsumer',
  'boundarySplatInstances',
  'boundarySplatMode',
  'boundarySplatOpacityGain',
  'boundarySplatRadianceGain',
  'boundarySplatRadius',
  'boundarySplatSharpness',
  'flowKernelDescriptorCapture',
  'selectiveHeadLiveRenderComposition',
  'selectiveHeadLiveRole',
  'volumeResidualFeatureDebug',
  'volumeResidualMode',
  'volumeResidualModelUrl',
  'volumeResidualStrength',

  'adaptiveRays',
  'majorantSkip',
  'majorantSmooth',
  'majorantGuard',
  'majorantGrid',
  'majorantCadence',
  'temporalAccum',
  'temporalJitter',
  'historyClamp',
]);
const RETIRED_RAYMARCH_CONTROL_RECEIPT_LIFETIME = 'volume-prototype-runtime-v0';

export function stripRetiredRaymarchControls(controls = {}) {
  const next = { ...controls };
  const retiredRaymarchControls = [];
  for (const key of RETIRED_RAYMARCH_CONTROL_KEYS) {
    if (!Object.hasOwn(next, key)) continue;
    retiredRaymarchControls.push({ key, value: next[key] });
    delete next[key];
  }
  return { controls: next, retiredRaymarchControls };
}

export function updateRetiredRaymarchControlReceipt(previousReceipt = [], observedReceipt = []) {
  const previousByKey = new Map(previousReceipt.map(row => [row.key, row]));
  const observedByKey = new Map(observedReceipt.map(row => [row.key, row]));
  return RETIRED_RAYMARCH_CONTROL_KEYS
    .map(key => previousByKey.get(key) || observedByKey.get(key))
    .filter(Boolean)
    .map(row => ({ key: row.key, value: row.value }));
}

export function retiredRaymarchControlReceiptPayload(source = {}) {
  if (!Object.hasOwn(source, 'retiredRaymarchControls')) {
    throw new Error('missing-retired-raymarch-controls-receipt');
  }
  if (!Array.isArray(source.retiredRaymarchControls)) {
    throw new Error('invalid-retired-raymarch-controls-receipt');
  }
  if (!Object.hasOwn(source, 'retiredRaymarchControlReceiptLifetime')) {
    throw new Error('missing-retired-raymarch-control-receipt-lifetime');
  }
  if (source.retiredRaymarchControlReceiptLifetime !== RETIRED_RAYMARCH_CONTROL_RECEIPT_LIFETIME) {
    throw new Error(`invalid-retired-raymarch-control-receipt-lifetime:${source.retiredRaymarchControlReceiptLifetime}`);
  }
  return {
    retiredRaymarchControls: source.retiredRaymarchControls.map(row => ({ key: row.key, value: row.value })),
    retiredRaymarchControlReceiptLifetime: source.retiredRaymarchControlReceiptLifetime,
  };
}

function normalizeVolumePresentationMode(value) {
  const requestedRaw = String(value || 'beauty').trim().toLowerCase();
  const requested = requestedRaw === 'intrinsic' ? 'intrinsic' : 'beauty';
  return {
    requestedRaw,
    requested,
    fallbackReason: requestedRaw === requested ? null : `unsupported-volume-presentation-mode:${requestedRaw}`,
  };
}

function normalizeRaymarchSmokePresentationMode(value) {
  const requestedRaw = String(value ?? 'on').trim().toLowerCase();
  const requested = requestedRaw === 'off' ? 'off' : 'on';
  return {
    requestedRaw,
    requested,
    fallbackReason: requestedRaw === requested ? null : `unsupported-raymarch-smoke-presentation-mode:${requestedRaw}`,
  };
}

function intrinsicPresentationOverrides(controls = {}) {
  return {
    ...controls,
    fireRenderMode: 'stock',
    shellInspectMode: 'boundary_fire',
    raySteps: controls.raySteps,
    adaptiveRays: controls.adaptiveRays,
    renderScale: controls.renderScale,
  };
}

function normalizeCanonicalSourceMode(value) {
  return Object.hasOwn(CANONICAL_SOURCE_MODE_VALUES, value) ? value : 'current';
}

function canonicalSourceModeValue(value) {
  return CANONICAL_SOURCE_MODE_VALUES[normalizeCanonicalSourceMode(value)] || 0;
}

function normalizeCanonicalRenderMode(value) {
  return Object.hasOwn(CANONICAL_RENDER_MODE_VALUES, value) ? value : 'default';
}

function canonicalRenderModeValue(value) {
  return CANONICAL_RENDER_MODE_VALUES[normalizeCanonicalRenderMode(value)] || 0;
}

function normalizeCanonicalMotionMode(value) {
  return Object.hasOwn(CANONICAL_LEGACY_MOTION_REQUEST_VALUES, value) ? value : 'animated';
}

export function canonicalMotionCompatibilityReceipt(value) {
  return {
    identity: CANONICAL_ANALYTIC_MOTION_RETIREMENT_IDENTITY,
    requested: normalizeCanonicalMotionMode(value),
    effective: 'retired',
    uniformValue: CANONICAL_ANALYTIC_MOTION_RETIRED_UNIFORM_VALUE,
  };
}

function normalizeCanonicalContentMode(value) {
  return Object.hasOwn(CANONICAL_CONTENT_MODE_VALUES, value) ? value : 'smoke';
}

export function canonicalSourceControlSignature(snapshot = {}) {
  return [
    normalizeVolumeScene(snapshot.volumeScene),
    snapshot.inputRadius,
    snapshot.flowRate,
    normalizeCanonicalSourceMode(snapshot.canonicalSourceMode),
    normalizeCanonicalContentMode(snapshot.canonicalContentMode),
    snapshot.canonicalSourceY,
    snapshot.canonicalSourceInjection,
    snapshot.canonicalBuoyancy,
  ].map(value => Number.isFinite(value) ? Number(value).toFixed(4) : String(value ?? '')).join('|');
}

function canonicalContentModeValue(value) {
  return CANONICAL_CONTENT_MODE_VALUES[normalizeCanonicalContentMode(value)] || 0;
}

function normalizeBoundarySidecarSource(value) {
  const normalized = String(value || 'live').toLowerCase().replace(/-/g, '_');
  if (normalized === 'baked' || normalized === 'mix' || normalized === 'override') return normalized;
  return 'live';
}

function boundarySidecarSourceValue(value) {
  const normalized = normalizeBoundarySidecarSource(value);
  if (normalized === 'baked' || normalized === 'override') return 1;
  if (normalized === 'mix') return 2;
  return 0;
}

function normalizeBoundarySidecarView(value) {
  const normalized = String(value || 'off').toLowerCase().replace(/-/g, '_');
  if (normalized === 'support' || normalized === 'coverage' || normalized === 'ridge' || normalized === 'proximity' || normalized === 'footprint') return normalized;
  return 'off';
}

function boundarySidecarViewValue(value) {
  const normalized = normalizeBoundarySidecarView(value);
  if (normalized === 'support') return 1;
  if (normalized === 'coverage') return 2;
  if (normalized === 'ridge') return 3;
  if (normalized === 'proximity') return 4;
  if (normalized === 'footprint') return 5;
  return 0;
}

// Consumers of the retained optical support field; independent of a renderer.
export function resolveBoundaryFieldExecutionPlan({boundarySidecarSource='live',boundarySidecarView='off',flamePriority=0,raymarchMode='numerical',explicitSidecarConsumer=null}={}) {
  const source=normalizeBoundarySidecarSource(boundarySidecarSource),view=normalizeBoundarySidecarView(boundarySidecarView);
  const consumer=source==='override'?'external-override':source!=='live'?'raymarch-structure':view!=='off'?'sidecar-view':raymarchMode==='numerical'&&Number(flamePriority)>0?'flame-guidance':explicitSidecarConsumer?String(explicitSidecarConsumer):'off';
  return {required:source!=='override'&&consumer!=='off',consumer,source,view};
}

export function validateFullFieldDerivedBufferMaterialization(derivedBuffers = {}) {
  if (derivedBuffers.boundarySidecarBuilt !== true) {
    return {ok:false,failurePhase:'derived-buffer-materialization',reason:'full-field-sidecar-not-built'};
  }
  return {ok:true,failurePhase:null,reason:null};
}

function normalizeFlowKernelStrength(value) {
  return clampFinite(value, 0, 1, 0);
}

function normalizeFlowKernelRadius(value) {
  return clampFinite(value, 0.0025, 0.12, 0.03);
}

function normalizeFlowKernelCoherence(value) {
  return clampFinite(value, 0, 2, 1);
}

function flowKernelRequestedControls(controls = {}) {
  return {
    strength: Number(controls.flowKernelStrength ?? 0),
    radiusWorld: Number(controls.flowKernelRadius ?? 0.03),
    coherence: Number(controls.flowKernelCoherence ?? 1),
  };
}

function flowKernelEffectiveControls(controls = {}) {
  return {
    strength: normalizeFlowKernelStrength(controls.flowKernelStrength),
    radiusWorld: normalizeFlowKernelRadius(controls.flowKernelRadius),
    coherence: normalizeFlowKernelCoherence(controls.flowKernelCoherence),
  };
}

function normalizeWindStrength(value) {
  return clampFinite(value, 0, 1.5, 0);
}

function normalizeWindAngle(value) {
  return clampFinite(value, -180, 180, 0);
}

function normalizeWindHeight(value) {
  return clampFinite(value, -0.8, 0.8, 0.15);
}

function normalizeReactionFuelScale(value) {
  return clampFinite(value, 0, 1.5, 1);
}

function normalizeLifecycleEffect(value) {
  const normalized = String(value || 'none').toLowerCase();
  return normalized === 'snuff' ? 'snuff' : 'none';
}

function normalizeLifecycleT(value) {
  return clampFinite(value, 0, 1, 0);
}

function normalizeQuenchVapor(value) {
  return clampFinite(value, 0, 2, 0);
}

function normalizeRuntimeQuality(value) {
  const normalized = String(value || 'live_high').toLowerCase().replace(/-/g, '_');
  if (['live_high', 'live', 'high', 'hero', 'default'].includes(normalized)) return 'live_high';
  if (['live_low', 'low', 'degraded', 'throttled'].includes(normalized)) return 'live_low';
  if (['holdover', 'hold', 'paused', 'freeze', 'frozen'].includes(normalized)) return 'holdover';
  if (['impostor', 'imposter', 'emergency', 'fallback', 'prerender'].includes(normalized)) return 'impostor';
  if (normalized === 'auto') return 'auto';
  return 'live_high';
}

function runtimeQualityEffectiveFromPressure(requested, gpuPressure) {
  const normalized = normalizeRuntimeQuality(requested);
  if (normalized !== 'auto') return normalized;
  const pressure = clampFinite(gpuPressure, 0, 1, 0);
  if (pressure >= 0.90) return 'impostor';
  if (pressure >= 0.70) return 'holdover';
  if (pressure >= 0.45) return 'live_low';
  return 'live_high';
}

export function applyRuntimeQualityControls(controls = {}) {
  const requested = normalizeRuntimeQuality(controls.runtimeQualityRequested);
  const gpuPressure = clampFinite(controls.gpuPressure, 0, 1, 0);
  const effective = runtimeQualityEffectiveFromPressure(requested, gpuPressure);
  const next = {
    ...controls,
    runtimeQualityRequested: requested,
    runtimeQualityEffective: effective,
    runtimeQualityReason: String(controls.runtimeQualityReason || 'unspecified').slice(0, 96) || 'unspecified',
    gpuPressure,
  };
  const cap = (key, limit) => {
    const current = Number(next[key]);
    if (Number.isFinite(current) && current > limit) next[key] = limit;
  };
  const floor = (key, limit) => {
    const current = Number(next[key]);
    if (Number.isFinite(current) && current < limit) next[key] = limit;
  };
  if (effective === 'live_low') {
    cap('renderScale', 0.75);
    cap('raySteps', 96);
    floor('adaptiveRays', 0.45);
  } else if (effective === 'holdover') {
    cap('renderScale', 0.70);
    cap('raySteps', 72);
    floor('adaptiveRays', 0.65);
    floor('occupancySkip', 0.25);
    next.pressureStrategy = 'global';
    next.pressureIterations = Math.min(1, Number.isFinite(Number(next.pressureIterations)) ? Number(next.pressureIterations) : 1);
  } else if (effective === 'impostor') {
    cap('renderScale', 0.60);
    cap('raySteps', 48);
    floor('adaptiveRays', 0.85);
    floor('occupancySkip', 0.45);
    next.pressureStrategy = 'global';
    next.pressureIterations = 0;
  }
  // Viewport Preview composes with whichever tier is in effect: it caps the
  // raymarch only, so the tier's simulation settings stand.
  if (next.viewportPreview === true) Object.assign(next, applyPreviewQualityCaps(next).controls);
  return next;
}

function runtimeQualityReceipt(controls = {}) {
  const requested = normalizeRuntimeQuality(controls.runtimeQualityRequested);
  const effective = runtimeQualityEffectiveFromPressure(controls.runtimeQualityEffective || requested, controls.gpuPressure);
  const gpuPressure = clampFinite(controls.gpuPressure, 0, 1, 0);
  const reason = String(controls.runtimeQualityReason || 'unspecified').slice(0, 96) || 'unspecified';
  return {
    identity: 'volume-runtime-quality-ladder-v0',
    requested,
    effective,
    viewportPreview: controls.viewportPreview === true,
    reason,
    gpuPressure,
    knobs: {
      renderScale: normalizeRenderScale(controls.renderScale),
      raySteps: clampFinite(controls.raySteps, 1, 160, 96),
      adaptiveRays: clampFinite(controls.adaptiveRays, 0, 1, 0.65),
      occupancySkip: clampFinite(controls.occupancySkip, 0, 1, 0.35),
      pressureStrategy: normalizePressureStrategy(controls.pressureStrategy, controls.volumeScene),
      pressureIterations: normalizePressureIterationCount(controls.pressureIterations, controls.volumeScene),
    },
  };
}

function snuffQuenchVaporStrength(controls = {}) {
  if (normalizeLifecycleEffect(controls.lifecycleEffect) !== 'snuff') return 0;
  const t = normalizeLifecycleT(controls.lifecycleT);
  const envelope = t * t * (3 - 2 * t);
  return normalizeQuenchVapor(controls.quenchVapor) * envelope;
}

function normalizeBonfireAblationValue(value, fallback = 1, max = 1.5) {
  return clampFinite(value, 0, max, fallback);
}

function normalizeBonfireAblationControls(controls = {}) {
  const requestedShear = normalizeBonfireAblationValue(controls.bonfireShear);
  const requestedTemporal = normalizeBonfireAblationValue(controls.bonfireTemporal);
  return {
    recenter: normalizeBonfireAblationValue(controls.bonfireRecenter),
    lateralDamping: normalizeBonfireAblationValue(controls.bonfireLateralDamping),
    shear: 0,
    detailForces: normalizeBonfireAblationValue(controls.bonfireDetailForces),
    depinch: normalizeBonfireAblationValue(controls.bonfireDepinch),
    projection: normalizeBonfireAblationValue(controls.bonfireProjection),
    temporal: 0,
    instabilityProbe: normalizeBonfireAblationValue(controls.bonfireInstabilityProbe, 0, 1),
    requestedShear,
    requestedTemporal,
    periodicMacroForcePolicy: MAIN_FLUID_BONFIRE_PERIODIC_MACRO_FORCE_STRATEGY_RETIRED,
  };
}

function volumeSceneMode(value) {
  return 1;
}

function detailScaleArtifactQuarantine(value) {
  return normalizeVolumeScene(value) === 'flame' ? 1 : 0;
}

function bonfireReferenceConfinementDebug(value) {
  const scene = normalizeVolumeScene(value);
  return {
    identity: 'bonfire-reference-front-gradient-confinement-v0',
    enabled: scene === 'bonfire_plume',
    storage: 'four-slot-existing-fluid-state',
    forceSource: 'neighbor-slot-front-gradient-plus-curl',
    radiancePolicy: 'front-contact-gated-emission',
  };
}

function minimalPlumeProofDebug(value) {
  const scene = normalizeVolumeScene(value);
  return {
    identity: 'minimal-canonical-plume-proof-v0',
    enabled: scene === 'canonical_plume',
    fieldView: 'density-smoke-readback',
    raymarchView: 'same-field-linear-volume-render',
    canonicalRenderSourceOrientation: 'screen-y-matches-source-field-y',
    excluded: 'bonfire-front-topology/fire-licks/microdetail/authored-bonfire-shape',
  };
}

function gridCellCount(gridSize, gridHeight = gridSize, gridDepth = gridSize) {
  return gridSize * gridHeight * gridDepth;
}

// Admission of a fluid box shape against a device's limits (report §34,
// review GH-04): the largest per-binding buffer is the fluid buffer
// (FLUID_COMPONENTS floats per cell); the largest 3-D texture extents are the
// height (burn-rate and force textures) and three widths (the force texture
// stacks its three components along depth). Checked before an existing field
// is destroyed, so a shape the device cannot hold is refused, not attempted.
// Unknown limits do not refuse.
export function gridShapeAdmission({ widthCells, heightCells }, limits = {}) {
  const finiteLimit = value => (Number.isFinite(Number(value)) && Number(value) > 0 ? Number(value) : Infinity);
  const fluidBytes = widthCells * heightCells * widthCells * FLUID_COMPONENTS * Float32Array.BYTES_PER_ELEMENT;
  const storageLimit = Math.min(finiteLimit(limits?.maxStorageBufferBindingSize), finiteLimit(limits?.maxBufferSize));
  const textureDimension = Math.max(heightCells, 3 * widthCells);
  const textureLimit = finiteLimit(limits?.maxTextureDimension3D);
  const receipt = { fluidBytes, storageLimit, textureDimension, textureLimit };
  if (fluidBytes > storageLimit) return { admitted: false, reason: `grid-shape-exceeds-device-storage-binding:${fluidBytes}>${storageLimit}`, ...receipt };
  if (textureDimension > textureLimit) return { admitted: false, reason: `grid-shape-exceeds-device-3d-texture-dimension:${textureDimension}>${textureLimit}`, ...receipt };
  return { admitted: true, reason: null, ...receipt };
}

function fluidBufferBytes(gridSize, gridHeight = gridSize, gridDepth = gridSize) {
  return gridCellCount(gridSize, gridHeight, gridDepth) * FLUID_COMPONENTS * Float32Array.BYTES_PER_ELEMENT;
}

// Largest storage buffer the volume prototype binds for one grid: fluid state
// over the tall domain, or a per-cell flow-kernel / boundary-splat buffer.
// The prototype's own device request and the shared host device both use it,
// so an adopted shared device is never smaller than the one the prototype owns.
function volumeStorageBufferRequestBytes(gridSize, cellCapacity = null, gridHeight = gridSize * VOLUME_VERTICAL_DOMAIN_EXTENT_MULTIPLIER) {
  return fluidBufferBytes(gridSize, gridHeight, gridSize);
}

function irradianceLatticeBufferBytes(irradianceGridSize = DEFAULT_FIRE_IRRADIANCE_GRID_SIZE, irradianceGridHeight = irradianceGridSize * VOLUME_VERTICAL_DOMAIN_EXTENT_MULTIPLIER) {
  return irradianceGridSize * irradianceGridHeight * irradianceGridSize * 4 * Float32Array.BYTES_PER_ELEMENT;
}

function normalizeFireIrradianceGridSize(value) {
  const parsed = Number(value);
  return SUPPORTED_FIRE_IRRADIANCE_GRID_SIZES.includes(parsed) ? parsed : DEFAULT_FIRE_IRRADIANCE_GRID_SIZE;
}

// One explicit GPUDevice for both the Three scene renderer and the Pyro volume
// simulator. Native same-device GPU texture sharing is the implementation
// ancestor; browser-canvas-to-Three CanvasTexture transport is the falsified
// path and must not carry scene lighting. The device must admit the storage
// the volume prototype would request for its own device (tall domain and
// per-cell buffers), declared composition buffers, and host requirements
// such as the SAM inference session's features and limits.
export async function requestKaminosSharedWebGpuDevice({
  bufferRequirements = {},
  hostRequirements = null,
  adapter: suppliedAdapter = null,
  acquireDevice,
} = {}) {
  // Hosts may install allocation accounting at acquisition, before Three or
  // the volume can allocate. The caller owns that policy; device requirements
  // and effective-capability validation stay here. Never bypass a refusal.
  if (acquireDevice !== undefined && typeof acquireDevice !== 'function') {
    throw new TypeError('shared-device acquireDevice must be a function');
  }
  const gpu = globalThis.navigator?.gpu;
  if (!suppliedAdapter && !gpu) throw new Error('WebGPU unavailable');
  const adapter = suppliedAdapter || await gpu.requestAdapter({
    powerPreference: 'high-performance',
    featureLevel: 'core',
  });
  if (!adapter) throw new Error('WebGPU adapter unavailable');
  const adapterLimit = name => Number(adapter.limits?.[name] || 0);
  const requiredLimits = {};
  const raise = (name, value) => { requiredLimits[name] = Math.max(requiredLimits[name] || 0, value); };

  const supportedStorageBytes = Math.min(adapterLimit('maxBufferSize'), adapterLimit('maxStorageBufferBindingSize'));
  if (supportedStorageBytes > 0) {
    // The tallest admissible shape at the widest grid (report §34): the device
    // is created once and the height can grow later without re-creating it.
    const volumeStorageBytes = Math.min(supportedStorageBytes, volumeStorageBufferRequestBytes(Math.max(...SUPPORTED_GRID_SIZES), null, Math.max(...SUPPORTED_GRID_SIZES) * GRID_HEIGHT_MAX_RATIO));
    raise('maxBufferSize', volumeStorageBytes);
    raise('maxStorageBufferBindingSize', volumeStorageBytes);
  }
  // Request the adapter's own per-stage storage-buffer capacity: the fluid
  // pipeline layouts include both compute work and composed smoke lighting.
  // A device must admit the entire pipeline, not only its largest bind group.
  const storageBuffersPerStage = adapterLimit('maxStorageBuffersPerShaderStage');
  if (storageBuffersPerStage < VOLUME_STORAGE_BUFFER_BINDING_COUNT) {
    throw new Error(
      `volume-layout-storage-buffer-limit:`
      + `required=${VOLUME_STORAGE_BUFFER_BINDING_COUNT}:supported=${storageBuffersPerStage}`,
    );
  }
  raise('maxStorageBuffersPerShaderStage', storageBuffersPerStage);
  // The shared device also owns Three's composed materials and authored
  // shadow maps. Enabling another light can exceed WebGPU's default16 even
  // though the adapter admits the layout. Preserve that actual capacity.
  const sampledTexturesPerStage = adapterLimit('maxSampledTexturesPerShaderStage');
  if (sampledTexturesPerStage > 0) raise('maxSampledTexturesPerShaderStage', sampledTexturesPerStage);
  for (const [name, required] of Object.entries({
    maxStorageBuffersInFragmentStage: 5,
    maxStorageBuffersInVertexStage: 4,
  })) {
    const available = adapterLimit(name);
    if (available < required) {
      throw new Error(`WebGPU adapter ${name} ${available} is below Kaminos shared-device requirement ${required}`);
    }
    raise(name, required);
  }
  // Composition requirements are known before any consumer receives the one
  // device. Only the two buffer capacity limits are admitted by this seam.
  if (!bufferRequirements || typeof bufferRequirements !== 'object' || Array.isArray(bufferRequirements)) {
    throw new Error('invalid composition buffer requirements');
  }
  for (const [name, required] of Object.entries(bufferRequirements)) {
    if (!['maxBufferSize', 'maxStorageBufferBindingSize'].includes(name)
      || !Number.isSafeInteger(required) || required <= 0) {
      throw new Error(`invalid composition buffer requirement ${name}`);
    }
    const available = adapterLimit(name);
    if (available < required) {
      throw new Error(`WebGPU adapter ${name} ${available} is below composition buffer requirement ${required}`);
    }
    raise(name, required);
  }
  // Host requirements (an object, or a function of the adapter such as the
  // SAM kit's device request): max* limits combine upward; alignment min*
  // limits combine downward and are satisfied by values at or below the request.
  const host = typeof hostRequirements === 'function' ? await hostRequirements(adapter) : (hostRequirements ?? {});
  if (!host || typeof host !== 'object') throw new Error('invalid shared-device host requirements');
  const hostLimits = host.requiredLimits ?? {};
  const hostFeatures = host.requiredFeatures == null ? [] : [...host.requiredFeatures];
  if (!hostLimits || typeof hostLimits !== 'object' || Array.isArray(hostLimits)) {
    throw new Error('invalid shared-device limit requirements');
  }
  for (const [name, required] of Object.entries(hostLimits)) {
    if (!Number.isSafeInteger(required) || required <= 0) {
      throw new Error(`invalid shared-device limit requirement ${name}`);
    }
    const available = adapterLimit(name);
    if (name.startsWith('min')) {
      if (!(available > 0 && available <= required)) {
        throw new Error(`WebGPU adapter ${name} ${available} cannot satisfy shared-device requirement ${required}`);
      }
      requiredLimits[name] = Object.hasOwn(requiredLimits, name) ? Math.min(requiredLimits[name], required) : required;
    } else {
      if (available < required) {
        throw new Error(`WebGPU adapter ${name} ${available} is below shared-device requirement ${required}`);
      }
      raise(name, required);
    }
  }
  if (hostFeatures.some(feature => typeof feature !== 'string' || !feature)) {
    throw new Error('invalid shared-device feature requirements');
  }
  const features = new Set(hostFeatures);
  if (adapter.features?.has?.('timestamp-query')) features.add('timestamp-query');
  // GPU-compressed mesh textures remain compressed only when the shared device
  // enables a format the adapter supports. Float filtering enables scene GI
  // source pyramids when supported; unsupported devices keep the base-level path.
  for(const feature of ['texture-compression-bc','texture-compression-etc2','texture-compression-astc','float32-filterable']) {
    if(adapter.features?.has?.(feature))features.add(feature);
  }
  for (const feature of features) {
    if (!adapter.features?.has?.(feature)) throw new Error(`WebGPU adapter feature ${feature} is unavailable`);
  }
  const requiredFeatures = [...features].sort();
  const descriptor = {
    requiredLimits,
    ...(requiredFeatures.length ? { requiredFeatures } : {}),
  };
  const device = await (acquireDevice
    ? acquireDevice(adapter, descriptor)
    : adapter.requestDevice(descriptor));
  for (const [name, required] of Object.entries(requiredLimits)) {
    const effective = Number(device.limits?.[name]);
    const satisfied = Number.isFinite(effective) && (name.startsWith('min') ? effective <= required : effective >= required);
    if (!satisfied) {
      device.destroy?.();
      throw new Error(`WebGPU effective device ${name} ${effective} does not satisfy shared-device requirement ${required}`);
    }
  }
  for (const feature of requiredFeatures) {
    if (!device.features?.has?.(feature)) {
      device.destroy?.();
      throw new Error(`WebGPU effective device feature ${feature} is unavailable`);
    }
  }
  return {
    identity: KAMINOS_SHARED_WEBGPU_DEVICE_IDENTITY,
    authority: 'single-explicit-device-three-and-volume-v0',
    adapter,
    device,
    queue: device.queue,
    requiredLimits,
    requiredFeatures,
  };
}

const SIM_COST_LEDGER_IDENTITY = 'tall-plume-sim-cost-ledger-v0';
const SIM_COST_LEDGER_EVIDENCE_SOURCE = 'cpu-structural-pass-ledger-plus-raf-queue-proxy';
const PRESSURE_SOURCE_STRATEGY_INLINE_DIVERGENCE = 'jacobi-inline-divergence-v0';
const PRESSURE_SOURCE_STRATEGY_RED_BLACK_SOR = 'red-black-sor-warm-start-v0';
const PRESSURE_SOURCE_STRATEGY_DISABLED = 'disabled';
// Converged pressure solver: opt-in red-black successive over-relaxation that
// iterates the same 7-point Laplacian in place to a small divergence residual,
// warm-started from the previous step's pressure. Legacy keeps the damped 1-3
// pass Jacobi with material-weighted partial projection so saved basins do not
// change under anyone.
export const PRESSURE_SOLVER_LEGACY = 'legacy';
export const PRESSURE_SOLVER_CONVERGED = 'converged';
export const PRESSURE_SOLVER_CONVERGED_OPEN_TOP = 'converged-open-top';
export const PRESSURE_SOLVER_IDENTITY = 'converged-red-black-sor-v0';
export const PRESSURE_SOLVER_SOR_OMEGA = 1.9;
export const PRESSURE_SOLVER_DEFAULT_SWEEPS = 60;
export const PRESSURE_SOLVER_MAX_SWEEPS = 1000;
export const PRESSURE_RESIDUAL_PROBE_INTERVAL_STEPS = 16;
export const PRESSURE_RESIDUAL_PROBE_FRESHNESS_FRAMES = 120;
// A residual map that has not settled within this wall time is retired even
// when no further simulation frame runs, so controlled captures that await the
// resolve are bounded too.
export const PRESSURE_RESIDUAL_MAP_TIMEOUT_MS = 5000;
const PRESSURE_RESIDUAL_MAP_TIMEOUT_ERROR = 'pressure-residual-map-timeout';
// Four vec4 partials per workgroup: compact divergence, wide divergence, vorticity (enstrophy sum, max |omega|), height profile (sum vertical velocity, heat, smoke).
export const PRESSURE_RESIDUAL_FLOATS_PER_WORKGROUP = 20;

// Pure fold of the probe's per-workgroup partials into the height profile.
// Workgroups are 4x4x4 cells, so each slab is four cell rows across the whole
// x-z plane; the fifth partial carries the lateral first moments of heat and
// smoke, which give a per-slab centroid in cells relative to the grid centre.
// A slab without material reports null, never zero: zero would read as centred.
export function residualProfileFromPartials(partials, { grid, workgroupsX, workgroupsY, workgroupCount }) {
  const slabCells = grid * grid * 4;
  const centre = (grid - 1) / 2;
  const zero = () => new Array(workgroupsY).fill(0);
  const vertical = zero(), heat = zero(), smoke = zero(), hot = zero(), heatX = zero(), heatZ = zero(), smokeX = zero(), smokeZ = zero();
  for (let i = 0; i < workgroupCount; i += 1) {
    const at = i * PRESSURE_RESIDUAL_FLOATS_PER_WORKGROUP;
    const slab = Math.floor(i / workgroupsX) % workgroupsY;
    vertical[slab] += partials[at + 12];
    heat[slab] += partials[at + 13];
    smoke[slab] += partials[at + 14];
    hot[slab] += partials[at + 15];
    heatX[slab] += partials[at + 16];
    heatZ[slab] += partials[at + 17];
    smokeX[slab] += partials[at + 18];
    smokeZ[slab] += partials[at + 19];
  }
  const centroid = (mass, mx, mz) => mass.map((m, slab) => (m > 1e-9 ? [mx[slab] / m - centre, mz[slab] / m - centre] : null));
  return {
    identity: 'height-profile-before-projection-v1',
    slabRows: 4,
    slabs: workgroupsY,
    verticalVelocityMean: vertical.map(sum => sum / slabCells),
    heatMean: heat.map(sum => sum / slabCells),
    smokeMean: smoke.map(sum => sum / slabCells),
    // Heat-weighted mean vertical velocity per slab: the hot gas's own rise speed.
    hotVerticalVelocityMean: hot.map((sum, slab) => (heat[slab] > 1e-9 ? sum / heat[slab] : 0)),
    // Where the hot gas and the smoke sit in the x-z plane, per slab, in cells
    // from the grid centre: a plume that leans shows a centroid that walks with height.
    heatCentroidCells: centroid(heat, heatX, heatZ),
    smokeCentroidCells: centroid(smoke, smokeX, smokeZ),
  };
}
const PRESSURE_SOLVER_VALUES = Object.freeze([PRESSURE_SOLVER_LEGACY, PRESSURE_SOLVER_CONVERGED, PRESSURE_SOLVER_CONVERGED_OPEN_TOP]);
const TALL_PLUME_PRESSURE_ITERATION_STRATEGY_PRESSURE2 = 'tall-plume-pressure2-v0';
const TALL_PLUME_PRESSURE_ITERATION_STRATEGY_INACTIVE = 'inactive';
const TALL_PLUME_SPATIAL_PRESSURE_TIER_STRATEGY = 'tall-plume-spatial-pressure-tiers-v0';
const TALL_PLUME_SPATIAL_PRESSURE_TIER_STRATEGY_INACTIVE = 'inactive';
const PRESSURE_PROJECTION_READ_STRATEGY_COMPOSITE = 'composite-pressure-tier-read-v0';
const PRESSURE_PROJECTION_READ_STRATEGY_SINGLE_BUFFER = 'single-pressure-buffer-read-v0';
const PRESSURE_STRATEGY_SPATIAL_TIERS = 'spatial_tiers';
const PRESSURE_STRATEGY_GLOBAL = 'global';
const DEFAULT_PRESSURE_TIER_LOWER_MAX = 0.50;
const DEFAULT_PRESSURE_TIER_HERO_MIN = 0.05;
const DEFAULT_PRESSURE_TIER_HERO_MAX = 0.22;
const DEFAULT_PRESSURE_TIER_OVERLAY = 0;
const MAIN_FLUID_KERNEL_STRATEGY_FIRE_LICK_BREAKUP = 'main-fluid-fire-lick-breakup-v0';
const MAIN_FLUID_KERNEL_STRATEGY_ZERO_FIRE_LICK_BYPASS = 'main-fluid-zero-fire-lick-bypass-v0';
const MAIN_FLUID_LOCAL_PROJECTION_STRATEGY_STAGED_PRESSURE_ONLY = 'main-fluid-local-projection-staged-pressure-only-v0';
