  let effectiveRaymarchSmokeSuppressed = raymarchSmokeSuppressed;
  let startT = max(hit.x, 0.0);
  let endT = min(hit.y, sceneDepthEndT);
  // Keep ordinary sample positions stable; clipping removes hidden samples,
